/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/event.h>
#include <nuttx/irq.h>
#include <nuttx/sched.h>

#include <errno.h>

#include \\\"event/event.h\\\"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int nx_event_post(FAR nx_event_t *event, uint32_t events)
{
  irqstate_t flags;
  int semcount;
  int ret;

  if (event == NULL)
    {
      return -EINVAL;
    }

  flags = enter_critical_section();

  event->events |= events;
  nx_sem_get_value(&event->sem, &semcount);

  /* If one or more tasks are waiting for events, wake them up */

  if (semcount < 0)
    {
       ret = nx_sem_post(&event->sem);
    }
  else
    {
      ret = OK;
    }

  leave_critical_section(flags);
  return ret;
}
